import type { DependencyPage, GraphProjectionBatch, GraphProjectionBookState, GraphProjectionConfig, GraphProjectionFailure, GraphProjectionGeneration, GraphProjectionHealth, GraphProjectionRequest, GraphProjectionSourceMapping, GraphTraversalKind, GraphTraversalResult } from "../../../common/contracts";
