async function saveMapping(client:PoolClient,generationId:string,item:ProjectionNodeInput|ProjectionEdgeInput,elementKind:"vertex"|"edge",label:string){await (async()=>{const values={id:randomUUID(),book_id:item.bookId,generation_id:generationId,element_kind:elementKind,graph_label:label,graph_element_key:item.projectionKey,source_kind:item.sourceKind,source_id:item.sourceId,source_version_id:item.sourceVersionId,source_revision:item.sourceRevision,source_hash:item.sourceHash,projection_hash:stableHash(item),status:"active",projected_at:new Date().toISOString(),tombstoned_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);await client.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',["graph_projection_source_mapping:"+JSON.stringify([values.generation_id,values.graph_element_key])]);const existing=(await listRecordCards(client,"graph_projection_source_mapping",{lock:true,where:{generation_id:values.generation_id,graph_element_key:values.graph_element_key}}))[0];if(existing)return{rows:[],rowCount:0};const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"graph_projection_source_mapping",title:"graph_projection_source_mapping",values});return{rows:[row],rowCount:1};})();}

export async function rebuildGraphProjection(bookId:string,input:{idempotencyKey:string;actor?:string}):Promise<GraphProjectionGeneration>{const pool=await getNewDesignPool(),client=await pool.connect();let generationId="",requestId="",batchId="",timeout=5000;try{const lock=(await client.query("SELECT pg_try_advisory_lock(hashtextextended($1,0)) acquired",[bookId])).rows[0];if(!lock?.acquired)throw new NewDesignError("该书已有图投影重建正在执行。",409,{code:"GRAPH_REBUILD_IN_PROGRESS"});await client.query("BEGIN");assertFound((await client.query("SELECT id FROM new_design.books WHERE id=$1 AND status='active' FOR UPDATE",[bookId])).rows[0],"书籍不存在或已归档。");const repeated=(await client.query("SELECT generation_id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,generation_id uuid,request_kind text,dependency_resource_id uuid,source_kind text,source_id uuid,source_version_id uuid,source_revision bigint,source_hash char(64),reason text,status text,attempt_count integer,idempotency_key text,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,started_at timestamptz,completed_at timestamptz) WHERE record.status='active') graph_projection_request_record WHERE book_id=$1 AND idempotency_key=$2",[bookId,input.idempotencyKey])).rows[0];if(repeated?.generation_id){const existing=assertFound((await client.query("SELECT * FROM new_design.graph_projection_runs WHERE id=$1",[repeated.generation_id])).rows[0],"图投影世代不存在。");await client.query("COMMIT");return mapGeneration(existing);}const cfg=await config(client),generation=Number((await client.query("SELECT COALESCE(max(generation),0)+1 value FROM new_design.graph_projection_runs WHERE book_id=$1",[bookId])).rows[0].value);timeout=Number(cfg.statement_timeout_ms);generationId=randomUUID();requestId=randomUUID();batchId=randomUUID();await client.query("INSERT INTO new_design.graph_projection_runs(id,book_id,generation,mapping_version) VALUES($1,$2,$3,$4)",[generationId,bookId,generation,cfg.mapping_version]);await (async()=>{const values={id:requestId,book_id:bookId,generation_id:generationId,request_kind:"full_rebuild",dependency_resource_id:null,source_kind:null,source_id:null,source_version_id:null,source_revision:null,source_hash:null,reason:`用户 ${input.actor??"system"} 请求全量重建。`,status:"processing",attempt_count:1,idempotency_key:input.idempotencyKey,last_error_code:"",last_error_detail:"",retryable:true,created_at:new Date().toISOString(),started_at:new Date().toISOString(),completed_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"graph_projection_request",title:"graph_projection_request",values});return{rows:[row],rowCount:1};})();await (async()=>{const values={id:batchId,request_id:requestId,book_id:bookId,generation_id:generationId,mode:"full_rebuild",status:"running",source_watermark:{},processed_count:0,vertex_count:0,edge_count:0,checksum:null,started_at:new Date().toISOString(),completed_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"graph_projection_batch",title:"graph_projection_batch",values});return{rows:[row],rowCount:1};})();await (async()=>{await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",["graph_projection_book_state:"+bookId]);const current=(await listRecordCards(client,"graph_projection_book_state",{where:{book_id:bookId},lock:true}))[0],now=new Date().toISOString();if(current)return replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,status:"building",last_request_at:now,revision:Number(current.revision)+1,updated_at:now}});const book=assertFound((await client.query("SELECT space_id FROM new_design.books WHERE id=$1",[bookId])).rows[0],"小说不存在。");return createRecordCard(client,{spaceId:String(book.space_id),typeKey:"graph_projection_book_state",title:"图投影状态",values:{book_id:bookId,active_generation_id:null,status:"building",last_request_at:now,last_success_at:null,last_error_code:"",last_error_detail:"",revision:1,updated_at:now}});})();await client.query("COMMIT");const result=await withAgeTransaction(timeout,async ageClient=>{const snapshot=await loadSnapshot(ageClient,bookId);let vertices=0,edges=0;for(const item of snapshot.nodes){const node={...item,generationId,projectionKey:key(generationId,item.sourceKind,item.sourceId,item.sourceVersionId)};await upsertAgeNode(ageClient,node);await saveMapping(ageClient,generationId,node,"vertex","ProjectedNode");vertices++;}for(const item of snapshot.edges){const edge={...item,generationId,projectionKey:key(generationId,item.sourceKind,item.sourceId,item.sourceVersionId),sourceProjectionKey:key(generationId,item.from.kind,item.from.id,item.from.versionId),targetProjectionKey:key(generationId,item.to.kind,item.to.id,item.to.versionId)};await upsertAgeEdge(ageClient,edge);await saveMapping(ageClient,generationId,edge,"edge","PROJECTED_RELATION");edges++;}const actual=await countAgeGeneration(ageClient,{bookId,generationId});if(actual.vertices!==vertices||actual.edges!==edges)throw new NewDesignError(`AGE 投影计数校验失败：期望 ${vertices}/${edges}，实际 ${actual.vertices}/${actual.edges}。`,409,{code:"GRAPH_COUNT_MISMATCH"});return{...snapshot,vertices,edges,checksum:stableHash({nodes:snapshot.nodes,edges:snapshot.edges})};});const finish=await pool.connect();try{await finish.query("BEGIN");await finish.query("INSERT INTO new_design.graph_projection_checkpoints(id,batch_id,checkpoint_key,source_watermark,processed_count,checksum) VALUES($1,$2,'snapshot_complete',$3::jsonb,$4,$5)",[randomUUID(),batchId,JSON.stringify(result.watermark),result.vertices+result.edges,result.checksum]);await (async()=>{const rows=[];for(const current of await listRecordCards(finish,"graph_projection_batch",{lock:true,where:{id:batchId}})){if(!(current.id===(batchId)))continue;const row=await replaceRecordCard(finish,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"succeeded",source_watermark:result.watermark,processed_count:result.vertices+result.edges,vertex_count:result.vertices,edge_count:result.edges,checksum:result.checksum,completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();await finish.query("UPDATE new_design.graph_projection_runs SET status='ready',source_watermark=$2::jsonb,vertex_count=$3,edge_count=$4,projection_checksum=$5,completed_at=now() WHERE id=$1",[generationId,JSON.stringify(result.watermark),result.vertices,result.edges,result.checksum]);const previous=(await finish.query("SELECT active_generation_id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_book_state' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(book_id uuid,active_generation_id uuid,status text,last_request_at timestamptz,last_success_at timestamptz,last_error_code text,last_error_detail text,revision bigint,updated_at timestamptz) WHERE record.status='active') graph_projection_book_state_record WHERE book_id=$1 FOR UPDATE",[bookId])).rows[0]?.active_generation_id;if(previous)await finish.query("UPDATE new_design.graph_projection_runs SET status='superseded' WHERE id=$1 AND status='active'",[previous]);await finish.query("UPDATE new_design.graph_projection_runs SET status='active',activated_at=now() WHERE id=$1 AND status='ready'",[generationId]);await (async()=>{const rows=[];for(const current of await listRecordCards(finish,"graph_projection_book_state",{lock:true,where:{book_id:bookId}})){if(!(current.book_id===(bookId)))continue;const row=await replaceRecordCard(finish,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,active_generation_id:generationId,status:"active",last_success_at:new Date().toISOString(),last_error_code:"",last_error_detail:"",revision:Number(current.revision)+1,updated_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();await (async()=>{const rows=[];for(const current of await listRecordCards(finish,"graph_projection_request",{lock:true,where:{id:requestId}})){if(!(current.id===(requestId)))continue;const row=await replaceRecordCard(finish,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"succeeded",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();const completed=assertFound((await finish.query("SELECT * FROM new_design.graph_projection_runs WHERE id=$1",[generationId])).rows[0],"图投影世代读取失败。");await finish.query("COMMIT");return mapGeneration(completed);}catch(error){await finish.query("ROLLBACK");throw error;}finally{finish.release();}}catch(error){await client.query("ROLLBACK").catch(()=>undefined);if(generationId&&requestId){const detail=error instanceof Error?error.message:String(error),code=projectionErrorCode(error,"GRAPH_REBUILD_FAILED");await pool.query("UPDATE new_design.graph_projection_runs SET status='failed',error_code=$2,error_detail=$3,completed_at=now() WHERE id=$1 AND status IN ('building','ready')",[generationId,code,detail]).catch(()=>undefined);await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_request",{lock:true,where:{id:requestId}})){if(!(current.id===(requestId)&&current.status===("processing")))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",last_error_code:code,last_error_detail:detail,completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_batch",{lock:true,where:{id:batchId}})){if(!(current.id===(batchId)))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);await await tx(async recordClient=>{const values={id:randomUUID(),request_id:requestId,batch_id:batchId,book_id:bookId,generation_id:generationId,stage:"rebuild",error_code:code,error_detail:detail,retryable:true,created_at:new Date().toISOString()};const spaceId=String(assertFound((await recordClient.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);const row=await createRecordCard(recordClient,{id:String(values.id),spaceId,typeKey:"graph_projection_failure",title:"graph_projection_failure",values});return{rows:[row],rowCount:1};}).catch(()=>undefined);await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_book_state",{lock:true,where:{book_id:bookId}})){if(!(current.book_id===(bookId)))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,status:(current.active_generation_id==null?"unavailable":"degraded"),last_error_code:code,last_error_detail:detail,revision:Number(current.revision)+1,updated_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);}throw error;}finally{try{await client.query("SELECT pg_advisory_unlock(hashtextextended($1,0))",[bookId]);client.release();}catch{client.release(true);}}}

async function isCurrentProjectionResource(client:PoolClient,request:Record<string,unknown>):Promise<boolean>{const kind=String(request.source_kind),id=request.source_id,version=request.source_version_id,book=request.book_id;const checks:Record<string,string>={card_version:"SELECT 1 FROM new_design.books book JOIN new_design.cards item ON item.space_id=book.space_id JOIN new_design.card_types author_type ON author_type.id=item.card_type_id AND NOT author_type.is_internal WHERE book.id=$3 AND item.id=$1 AND item.current_version_id=$2 AND item.status='active'",chapter_body_version:"SELECT 1 FROM new_design.chapter_documents item WHERE item.book_id=$3 AND item.id=$1 AND item.adopted_version_id=$2 AND item.status='active'",canonical_fact:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='canonical_fact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,subject_card_id uuid,predicate text,value_kind text,value_json jsonb,value_hash char(64),object_card_id uuid,valid_story_start numeric,valid_story_end numeric,status text,confidence numeric(5,4),source_method text,supersedes_fact_id uuid,superseded_by_fact_id uuid,revision integer,created_by text,created_at timestamptz,updated_at timestamptz) WHERE record.status='active') item WHERE item.book_id=$3 AND item.id=$1 AND item.id=$2 AND item.status='confirmed'",state_change:"SELECT 1 FROM (SELECT fields.book_id,fields.subject_kind,fields.subject_id,fields.state_key,record_version.values->'value_json' AS value_json,fields.source_initial_version_id,fields.source_state_change_id,fields.projection_revision,fields.is_stale,fields.rebuilt_at FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='current_state_projection' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(book_id uuid,subject_kind text,subject_id uuid,state_key text,value_json jsonb,source_initial_version_id uuid,source_state_change_id uuid,projection_revision bigint,is_stale boolean,rebuilt_at timestamptz) WHERE record.status='active') projection JOIN (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='state_change' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,sequence bigint,book_id uuid,settlement_id uuid,proposal_id uuid,chapter_document_id uuid,body_version_id uuid,text_anchor_id uuid,cause_event_card_id uuid,subject_kind text,subject_id uuid,state_key text,before_json jsonb,after_json jsonb,delta_json jsonb,reason text,effective_story_order numeric,status text,created_at timestamptz) WHERE record.status='active') change ON change.id=projection.source_state_change_id WHERE projection.book_id=$3 AND change.id=$1 AND change.id=$2 AND change.status='active' AND NOT projection.is_stale",knowledge_state_change:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='current_knowledge_state_projection' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(book_id uuid,holder_kind text,holder_key text,holder_card_id uuid,claim_id uuid,source_change_id uuid,stance text,confidence numeric,effective_story_order numeric,effective_narrative_order numeric,projection_revision bigint,rebuilt_at timestamptz) WHERE record.status='active') projection JOIN (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='knowledge_state_change' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,sequence bigint,book_id uuid,proposal_id uuid,proposal_version_id uuid,claim_id uuid,holder_kind text,holder_key text,holder_card_id uuid,stance text,confidence numeric,effective_story_order numeric,effective_narrative_order numeric,status text,confirmed_by text,created_at timestamptz) WHERE record.status='active') change ON change.id=projection.source_change_id WHERE projection.book_id=$3 AND change.proposal_id=$1 AND change.id=$2 AND change.status='active'",story_event_timing:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='story_event_timing' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,sequence bigint,book_id uuid,event_card_id uuid,proposal_id uuid,proposal_version_id uuid,lifecycle text,status text,time_mode text,start_certainty text,end_certainty text,start_instant timestamptz,end_instant timestamptz,timezone_name text,calendar_key text,start_label text,end_label text,normalized_start numeric,normalized_end numeric,duration_value numeric,duration_unit text,relative_to_event_card_id uuid,relative_relation text,relative_offset numeric,evidence_kind text,chapter_document_id uuid,body_version_id uuid,text_anchor_id uuid,fact_id uuid,plan_version_id uuid,state_proposal_id uuid,replaces_timing_id uuid,confirmed_by text,reason text,confirmed_at timestamptz) WHERE record.status='active') item WHERE item.book_id=$3 AND item.id=$1 AND item.id=$2 AND item.status='active'",story_event_relation:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='story_event_relation' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,sequence bigint,book_id uuid,proposal_id uuid,proposal_version_id uuid,relation_family text,relation_type text,source_event_card_id uuid,target_event_card_id uuid,confidence numeric,status text,confirmed_by text,reason text,created_at timestamptz) WHERE record.status='active') item WHERE item.book_id=$3 AND item.proposal_id=$1 AND item.id=$2 AND item.status='active'",planning_version:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='planning_object' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,level text,parent_object_id uuid,card_id uuid,title text,sort_order integer,status text,current_version_id uuid,adopted_version_id uuid,revision integer,created_at timestamptz,updated_at timestamptz) WHERE record.status='active') object JOIN (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='planning_version' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,object_id uuid,book_id uuid,version integer,base_version_id uuid,based_on_parent_version_id uuid,source text,status text,content jsonb,content_hash char(64),source_body_version_id uuid,created_by text,stale_at timestamptz,stale_reason text,created_at timestamptz) WHERE record.status='active') version ON version.id=object.adopted_version_id WHERE object.book_id=$3 AND object.id=$1 AND version.id=$2 AND object.status='active' AND version.stale_at IS NULL",research_record_version:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='book_research_reference' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,research_version_id uuid,pack_version_id uuid,purpose text,compiled_snapshot jsonb,created_at timestamptz) WHERE record.status='active') reference JOIN (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='research_record_version' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,record_id uuid,version integer,parent_version_id uuid,source_scope jsonb,template_key text,template_version integer,run_status text,progress integer,budget_tokens integer,used_tokens integer,prompt_snapshot jsonb,model_snapshot jsonb,input_snapshot jsonb,structured_result jsonb,report text,last_error text,cancel_requested boolean,run_hash text,created_at timestamptz,completed_at timestamptz) WHERE record.status='active') version ON version.id=reference.research_version_id WHERE reference.book_id=$3 AND version.record_id=$1 AND version.id=$2",asset_version:"SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='asset' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,space_id uuid,book_id uuid,asset_key text,asset_kind text,title text,status text,current_version_id uuid,revision integer,created_by text,created_at timestamptz,updated_at timestamptz,archived_at timestamptz) WHERE record.status='active') item WHERE item.book_id=$3 AND item.id=$1 AND item.current_version_id=$2 AND item.status='active'",card_relation:"SELECT 1 FROM new_design.books book JOIN new_design.card_relations item ON item.space_id=book.space_id WHERE book.id=$3 AND item.id=$1 AND item.id=$2 AND item.status='active'"};const sql=checks[kind];return sql?Boolean((await client.query(sql,[id,version,book])).rowCount):false;}

export async function recoverInterruptedGraphRebuild(bookId:string):Promise<number>{
  const pool=await getNewDesignPool(),client=await pool.connect();
  let locked=false;
  try{
    locked=Boolean((await client.query("SELECT pg_try_advisory_lock(hashtextextended($1,0)) acquired",[bookId])).rows[0]?.acquired);
    if(!locked)throw new NewDesignError("该书已有图投影操作正在执行。",409,{code:"GRAPH_REBUILD_IN_PROGRESS"});
    await client.query("BEGIN");
    const interrupted=(await client.query("SELECT request.id,request.generation_id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,generation_id uuid,request_kind text,dependency_resource_id uuid,source_kind text,source_id uuid,source_version_id uuid,source_revision bigint,source_hash char(64),reason text,status text,attempt_count integer,idempotency_key text,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,started_at timestamptz,completed_at timestamptz) WHERE record.status='active') request JOIN new_design.graph_projection_runs generation ON generation.id=request.generation_id WHERE request.book_id=$1 AND request.request_kind='full_rebuild' AND request.status='processing' AND generation.status IN ('building','ready') FOR UPDATE OF request,generation",[bookId])).rows;
    for(const row of interrupted){
      await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_batch",{lock:true,where:{request_id:row.id}})){if(!(current.request_id===(row.id)&&current.status===("running")))continue;const savedRow=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",completed_at:new Date().toISOString()}});rows.push(savedRow);}return{rows,rowCount:rows.length};})();
      await client.query("UPDATE new_design.graph_projection_runs SET status='failed',error_code='interrupted_rebuild',error_detail='上次全量构建未完成，原世代保留以供核对。',completed_at=now() WHERE id=$1",[row.generation_id]);
      await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_request",{lock:true,where:{id:row.id}})){if(!(current.id===(row.id)))continue;const savedRow=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",last_error_code:"interrupted_rebuild",last_error_detail:"上次全量构建未完成，需重新建立世代。",completed_at:new Date().toISOString()}});rows.push(savedRow);}return{rows,rowCount:rows.length};})();
    }
    if(interrupted.length)await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_book_state",{lock:true,where:{book_id:bookId}})){if(!(current.book_id===(bookId)))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,status:(current.active_generation_id==null?"unavailable":"degraded"),last_error_code:"interrupted_rebuild",last_error_detail:"上次全量构建未完成，需重新建立世代。",revision:Number(current.revision)+1,updated_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
    await client.query("COMMIT");
    return interrupted.length;
  }catch(error){await client.query("ROLLBACK").catch(()=>undefined);throw error;}
  finally{if(locked){try{await client.query("SELECT pg_advisory_unlock(hashtextextended($1,0))",[bookId]);client.release();}catch{client.release(true);}}else client.release();}
}

export async function processGraphProjectionRequest(id:string):Promise<GraphProjectionRequest>{
  const pool=await getNewDesignPool(),client=await pool.connect();
  let request:Record<string,unknown>|null=null;
  let batchId="";
  let generationId="";
  let bookId="";
  let locked=false;
  try{
    bookId=String(assertFound((await client.query("SELECT book_id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,generation_id uuid,request_kind text,dependency_resource_id uuid,source_kind text,source_id uuid,source_version_id uuid,source_revision bigint,source_hash char(64),reason text,status text,attempt_count integer,idempotency_key text,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,started_at timestamptz,completed_at timestamptz) WHERE record.status='active') graph_projection_request_record WHERE id=$1",[id])).rows[0],"图同步请求不存在。").book_id);
    locked=Boolean((await client.query("SELECT pg_try_advisory_lock(hashtextextended($1,0)) acquired",[bookId])).rows[0]?.acquired);
    if(!locked)throw new NewDesignError("该书已有图投影操作正在执行。",409,{code:"GRAPH_REBUILD_IN_PROGRESS"});
    await client.query("BEGIN");
    const activeRequest=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,generation_id uuid,request_kind text,dependency_resource_id uuid,source_kind text,source_id uuid,source_version_id uuid,source_revision bigint,source_hash char(64),reason text,status text,attempt_count integer,idempotency_key text,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,started_at timestamptz,completed_at timestamptz) WHERE record.status='active') graph_projection_request_record WHERE id=$1 FOR UPDATE",[id])).rows[0],"图同步请求不存在。");
    if(activeRequest.request_kind==="full_rebuild")throw new NewDesignError("全量重建请求必须通过书籍重建入口执行。",409);
    if(activeRequest.status==="processing"){
      await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_batch",{lock:true,where:{request_id:id}})){if(!(current.request_id===(id)&&current.status===("running")))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
      await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_request",{lock:true,where:{id:id}})){if(!(current.id===(id)))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",last_error_code:"interrupted_projection",last_error_detail:"上次处理未完成，已在书籍锁保护下重新执行。",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
      activeRequest.status="failed";
    }
    if(!["pending","failed"].includes(String(activeRequest.status)))throw new NewDesignError("图同步请求当前不可执行。",409);
    const state=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_book_state' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(book_id uuid,active_generation_id uuid,status text,last_request_at timestamptz,last_success_at timestamptz,last_error_code text,last_error_detail text,revision bigint,updated_at timestamptz) WHERE record.status='active') graph_projection_book_state_record WHERE book_id=$1 AND active_generation_id IS NOT NULL",[activeRequest.book_id])).rows[0],"书籍尚无可用图投影世代。");
    const cfg=await config(client);
    generationId=String(state.active_generation_id);
    batchId=randomUUID();
    await (async()=>{const rows=[];for(const current of await listRecordCards(client,"graph_projection_request",{lock:true,where:{id:id}})){if(!(current.id===(id)))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"processing",generation_id:state.active_generation_id,attempt_count:Number(current.attempt_count)+1,started_at:new Date().toISOString(),completed_at:null,last_error_code:"",last_error_detail:""}});rows.push(row);}return{rows,rowCount:rows.length};})();
    await (async()=>{const values={id:batchId,request_id:id,book_id:activeRequest.book_id,generation_id:state.active_generation_id,mode:"incremental",status:"running",source_watermark:{},processed_count:0,vertex_count:0,edge_count:0,checksum:null,started_at:new Date().toISOString(),completed_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"graph_projection_batch",title:"graph_projection_batch",values});return{rows:[row],rowCount:1};})();
    await client.query("COMMIT");
    request={...activeRequest,generation_id:generationId,status:"processing"};
    return await withAgeTransaction(Number(cfg.statement_timeout_ms),async ageClient=>{
      const currentGeneration=(await ageClient.query("SELECT active_generation_id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_book_state' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(book_id uuid,active_generation_id uuid,status text,last_request_at timestamptz,last_success_at timestamptz,last_error_code text,last_error_detail text,revision bigint,updated_at timestamptz) WHERE record.status='active') graph_projection_book_state_record WHERE book_id=$1",[activeRequest.book_id])).rows[0]?.active_generation_id;
      if(String(currentGeneration??"")!==generationId)throw new NewDesignError("处理期间图投影已切换世代，请重试该同步请求。",409,{code:"GRAPH_GENERATION_CHANGED"});
      const source={bookId:String(activeRequest.book_id),generationId,sourceKind:String(activeRequest.source_kind),sourceId:String(activeRequest.source_id),sourceVersionId:String(activeRequest.source_version_id)};
      const shouldTombstone=activeRequest.request_kind==="tombstone"||!(await isCurrentProjectionResource(ageClient,activeRequest));
      let vertexCount=0,edgeCount=0;
      if(shouldTombstone){
        await tombstoneAgeSource(ageClient,source);
        await (async()=>{const rows=[];for(const current of await listRecordCards(ageClient,"graph_projection_source_mapping",{lock:true,where:{generation_id:state.active_generation_id,source_kind:source.sourceKind,source_id:source.sourceId,source_version_id:source.sourceVersionId}})){if(!(current.generation_id===(state.active_generation_id)&&current.source_kind===(source.sourceKind)&&current.source_id===(source.sourceId)&&current.source_version_id===(source.sourceVersionId)&&current.status===("active")))continue;const row=await replaceRecordCard(ageClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_source_mapping",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"tombstoned",tombstoned_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
      }else{
        const snapshot=await loadSnapshot(ageClient,source.bookId);
        const nodes=snapshot.nodes.filter(item=>item.sourceKind===source.sourceKind&&item.sourceId===source.sourceId&&item.sourceVersionId===source.sourceVersionId);
        const edges=snapshot.edges.filter(item=>(item.sourceKind===source.sourceKind&&item.sourceId===source.sourceId&&item.sourceVersionId===source.sourceVersionId)||(item.from.kind===source.sourceKind&&item.from.id===source.sourceId&&item.from.versionId===source.sourceVersionId)||(item.to.kind===source.sourceKind&&item.to.id===source.sourceId&&item.to.versionId===source.sourceVersionId));
        if(nodes.length===0&&edges.length===0)throw new NewDesignError("当前资源没有匹配的 AGE 投影定义。",409,{code:"GRAPH_MAPPING_MISSING"});
        for(const item of nodes){const node={...item,generationId,projectionKey:key(generationId,item.sourceKind,item.sourceId,item.sourceVersionId)};await upsertAgeNode(ageClient,node);await saveMapping(ageClient,generationId,node,"vertex","ProjectedNode");vertexCount++;}
        for(const item of edges){const edge={...item,generationId,projectionKey:key(generationId,item.sourceKind,item.sourceId,item.sourceVersionId),sourceProjectionKey:key(generationId,item.from.kind,item.from.id,item.from.versionId),targetProjectionKey:key(generationId,item.to.kind,item.to.id,item.to.versionId)};await upsertAgeEdge(ageClient,edge);await saveMapping(ageClient,generationId,edge,"edge","PROJECTED_RELATION");edgeCount++;}
      }
      const activeCounts=await countAgeGeneration(ageClient,{bookId:source.bookId,generationId}),processedCount=Math.max(1,vertexCount+edgeCount),watermark={dependencyResourceId:activeRequest.dependency_resource_id,sourceKind:source.sourceKind,sourceId:source.sourceId,sourceVersionId:source.sourceVersionId},checksum=stableHash({requestId:id,action:shouldTombstone?"tombstone":"upsert",watermark,vertexCount,edgeCount});
      await ageClient.query("INSERT INTO new_design.graph_projection_checkpoints(id,batch_id,checkpoint_key,source_watermark,processed_count,checksum) VALUES($1,$2,'incremental_complete',$3::jsonb,$4,$5)",[randomUUID(),batchId,JSON.stringify(watermark),processedCount,checksum]);
      await (async()=>{const rows=[];for(const current of await listRecordCards(ageClient,"graph_projection_batch",{lock:true,where:{id:batchId}})){if(!(current.id===(batchId)))continue;const row=await replaceRecordCard(ageClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"succeeded",source_watermark:watermark,processed_count:processedCount,vertex_count:vertexCount,edge_count:edgeCount,checksum:checksum,completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
      await ageClient.query("UPDATE new_design.graph_projection_runs SET source_watermark=$2::jsonb,vertex_count=$3,edge_count=$4,projection_checksum=NULL WHERE id=$1 AND status='active'",[generationId,JSON.stringify(watermark),activeCounts.vertices,activeCounts.edges]);
      const completed=assertFound((await (async()=>{const rows=[];for(const current of await listRecordCards(ageClient,"graph_projection_request",{lock:true,where:{id:id}})){if(!(current.id===(id)))continue;const row=await replaceRecordCard(ageClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"succeeded",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})()).rows[0],"图同步请求完成状态写入失败。");
      await (async()=>{const rows=[];for(const current of await listRecordCards(ageClient,"graph_projection_book_state",{lock:true,where:{book_id:source.bookId,active_generation_id:generationId}})){if(!(current.book_id===(source.bookId)&&current.active_generation_id===(generationId)))continue;const row=await replaceRecordCard(ageClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,status:"active",last_success_at:new Date().toISOString(),last_error_code:"",last_error_detail:"",revision:Number(current.revision)+1,updated_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();
      return mapRequest(completed);
    });
  }catch(error){
    await client.query("ROLLBACK").catch(()=>undefined);
    if(request){
      const failedRequest=request;
      const detail=error instanceof Error?error.message:String(error);
      const code=projectionErrorCode(error,"GRAPH_SYNC_FAILED");
      await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_request",{lock:true,where:{id:id}})){if(!(current.id===(id)&&current.status===("processing")))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_request",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",last_error_code:code,last_error_detail:detail,completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);
      await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_batch",{lock:true,where:{id:batchId}})){if(!(current.id===(batchId)&&current.status===("running")))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_batch",values:{...current,revision:Number(current.revision)+1,updated_at:new Date().toISOString(),status:"failed",completed_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);
      await await tx(async recordClient=>{const values={id:randomUUID(),request_id:id,batch_id:batchId,book_id:failedRequest.book_id,generation_id:generationId,stage:"incremental",error_code:code,error_detail:detail,retryable:true,created_at:new Date().toISOString()};const spaceId=String(assertFound((await recordClient.query('SELECT space_id FROM new_design.books WHERE id=$1',[values.book_id])).rows[0],'所属小说不存在。').space_id);const row=await createRecordCard(recordClient,{id:String(values.id),spaceId,typeKey:"graph_projection_failure",title:"graph_projection_failure",values});return{rows:[row],rowCount:1};}).catch(()=>undefined);
      await await tx(async recordClient=>{const rows=[];for(const current of await listRecordCards(recordClient,"graph_projection_book_state",{lock:true,where:{book_id:failedRequest.book_id,active_generation_id:generationId}})){if(!(current.book_id===(failedRequest.book_id)&&current.active_generation_id===(generationId)))continue;const row=await replaceRecordCard(recordClient,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"graph_projection_book_state",values:{...current,status:"degraded",last_error_code:code,last_error_detail:detail,revision:Number(current.revision)+1,updated_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};}).catch(()=>undefined);
    }
    throw error;
  }finally{if(locked){try{await client.query("SELECT pg_advisory_unlock(hashtextextended($1,0))",[bookId]);client.release();}catch{client.release(true);}}else client.release();}
}

export async function traverseGraph(input:{bookId:string;queryKind:GraphTraversalKind;sourceKind:string;sourceId:string;targetSourceKind?:string|null;targetSourceId?:string|null;depth?:number;limit?:number}):Promise<GraphTraversalResult>{const pool=await getNewDesignPool(),client=await pool.connect();try{const cfg=await config(client),state=await stateWith(client,input.bookId);if(!state.activeGenerationId)throw new NewDesignError("该书尚无已激活的 AGE 投影。",409);const depth=Math.min(Number(cfg.max_depth),Math.max(1,input.depth??3)),limit=Math.min(Number(cfg.max_results),Math.max(1,input.limit??50));if(input.queryKind==="shortest_path"&&(!input.targetSourceKind||!input.targetSourceId))throw new NewDesignError("最短路径查询必须指定目标来源。",422);const paths=await withAgeTransaction(Number(cfg.statement_timeout_ms),ageClient=>runAgeTraversal(ageClient,{...input,generationId:state.activeGenerationId!,depth,limit}));return{bookId:input.bookId,generationId:state.activeGenerationId,queryKind:input.queryKind,paths,truncated:paths.length===limit};}finally{client.release();}}

export async function getGraphProjectionBatch(requestId:string):Promise<GraphProjectionBatch|null>{const pool=await getNewDesignPool(),row=(await pool.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_batch' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,request_id uuid,book_id uuid,generation_id uuid,mode text,status text,source_watermark jsonb,processed_count bigint,vertex_count bigint,edge_count bigint,checksum char(64),started_at timestamptz,completed_at timestamptz) WHERE record.status='active') graph_projection_batch_record WHERE request_id=$1 ORDER BY started_at DESC,id DESC LIMIT 1",[requestId])).rows[0];return row?mapBatch(row):null;}
export async function listGraphProjectionBatches(requestId:string,limit=50):Promise<GraphProjectionBatch[]>{const pool=await getNewDesignPool();return(await pool.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='graph_projection_batch' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,request_id uuid,book_id uuid,generation_id uuid,mode text,status text,source_watermark jsonb,processed_count bigint,vertex_count bigint,edge_count bigint,checksum char(64),started_at timestamptz,completed_at timestamptz) WHERE record.status='active') graph_projection_batch_record WHERE request_id=$1 ORDER BY started_at DESC,id DESC LIMIT $2",[requestId,Math.min(200,limit)])).rows.map(mapBatch);}
async function tx<T>(run:(client:PoolClient)=>Promise<T>):Promise<T>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const value=await run(client);await client.query("COMMIT");return value;}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}
